package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class KeyedObjects2D_getObject_TriageGen0Test {

    private KeyedObjects2D keyedObjects2D;
    private static final String ROW_KEY_1 = "Row1";
    private static final String ROW_KEY_2 = "Row2";
    private static final String COL_KEY_1 = "Col1";
    private static final String COL_KEY_2 = "Col2";
    private static final String TEST_VALUE = "TestData";

    @Before
    public void setUp() {
        keyedObjects2D = new KeyedObjects2D();
    }

    @Test
    public void testGetObject_Success() {
        keyedObjects2D.addObject(TEST_VALUE, ROW_KEY_1, COL_KEY_1);
        Object result = keyedObjects2D.getObject(ROW_KEY_1, COL_KEY_1);
        assertEquals("Should return the correct object for valid keys", TEST_VALUE, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetObject_NullRowKey() {
        keyedObjects2D.getObject(null, COL_KEY_1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetObject_NullColumnKey() {
        keyedObjects2D.getObject(ROW_KEY_1, null);
    }

    @Test(expected = UnknownKeyException.class)
    public void testGetObject_UnknownRowKey() {
        // Row key does not exist in the collection
        keyedObjects2D.getObject("UnknownRow", COL_KEY_1);
    }

    @Test(expected = UnknownKeyException.class)
    public void testGetObject_UnknownColumnKey() {
        // Row exists, but column key does not
        keyedObjects2D.addObject(TEST_VALUE, ROW_KEY_1, COL_KEY_1);
        keyedObjects2D.getObject(ROW_KEY_1, "UnknownCol");
    }

    @Test
    public void testGetObject_ValueIsNull() {
        // Testing case where the key is valid but the stored value is null
        keyedObjects2D.setObject(null, ROW_KEY_1, COL_KEY_1);
        // First, ensure keys are registered by adding something else or using setObject
        // Based on implementation, addObject/setObject populates row/column keys
        keyedObjects2D.addObject("Temp", ROW_KEY_1, COL_KEY_1);
        keyedObjects2D.setObject(null, ROW_KEY_1, COL_KEY_1);

        Object result = keyedObjects2D.getObject(ROW_KEY_1, COL_KEY_1);
        assertNull("Should return null if the value stored is null", result);
    }
}
